import{_ as a,H as t,f as l,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"第87讲 | 刘俊强：管理者必备的高效会议指南（下）","description":"","frontmatter":{},"headers":[{"level":2,"title":"创建会议议程","slug":"创建会议议程","link":"#创建会议议程","children":[]},{"level":2,"title":"跟进承诺任务","slug":"跟进承诺任务","link":"#跟进承诺任务","children":[]},{"level":2,"title":"结束会议","slug":"结束会议","link":"#结束会议","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"作者介绍","slug":"作者介绍","link":"#作者介绍","children":[]}],"relativePath":"技术领导力实战笔记/第87讲-刘俊强：管理者必备的高效会议指南（下）.md","filePath":"技术领导力实战笔记/第87讲-刘俊强：管理者必备的高效会议指南（下）.md","lastUpdated":1779820369000}'),p={name:"技术领导力实战笔记/第87讲-刘俊强：管理者必备的高效会议指南（下）.md"};function r(n,e,o,s,h,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="第87讲-刘俊强-管理者必备的高效会议指南-下" tabindex="-1">第87讲 | 刘俊强：管理者必备的高效会议指南（下） <a class="header-anchor" href="#第87讲-刘俊强-管理者必备的高效会议指南-下" aria-label="Permalink to &quot;第87讲 | 刘俊强：管理者必备的高效会议指南（下）&quot;">​</a></h1><p>你好，我是腾讯云资深架构师、TGO鲲鹏会会员刘俊强，有着8年以上的技术管理经验。会议是技术管理者保持沟通、推动工作的必要手段，因此，如何确保会议高效且有效，是技术管理者必备的技能之一。</p><p>昨天的文章中，我跟你分享了举办高效会议的六大原则，包括明确目的、确认时间、必备议程、做好准备、专注重点以及会议负责人。还和你分享了会议负责人的重要性，他能确保会议遵循其余五个原则，能使会议专注于目标并实现目标、确保会议按时开始和结束，因此，每个会议都要确保有一位会议负责人。</p><p>今天，我将继续“管理者必备的高效会议指南”的下篇，与你分享创建会议议程的具体策略、贴士和技巧，以及在会议结束后该做的跟进工作等。</p><h2 id="创建会议议程" tabindex="-1">创建会议议程 <a class="header-anchor" href="#创建会议议程" aria-label="Permalink to &quot;创建会议议程&quot;">​</a></h2><p>这里我有一个会议议程的模板，根据你选择会议的类型，模板的某些部分不一定完整匹配你的需求，你可以随意调整这个议程模板并创建属于自己的议程模板。接下来，我将简单介绍该模板的使用指南，也就是怎么利用会议议程模板来举行高效会议。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/38215/5d1614673e566d39d6141c4a4be6ac0d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/38215/5d1614673e566d39d6141c4a4be6ac0d.png" alt=""></a></p><p>我们先看看这个模板的左侧，这些是你在开会时要记住的重要指南，是我们举行会议时的重要参考，因为往往容易被忽略，所以我们再拿出来回顾下，从上至下分别是：</p><ol><li>最终结果是什么？例如，在每次会议结束时，所有与会者都应该感受到被尊重，重视并且明确未来的行动步骤等。</li><li>为什么要举行此次会议？例如工作协作或协调类会议，帮助减少合作时的摩擦等。</li><li>与会人员，谁应该参加这次会议？何时举行会议，我们应该多久见面一次？</li><li>如何衡量会议是否成功？比如与会者请求帮助，会上成功给予其完成工作的必要帮助。</li><li>工具或资源需求有哪些？例如必要的资料（开发、产品），承诺完成的相关资料，会议记录和代办事项的系统等。</li></ol><p>再次强调，模版不一定完全匹配你的需求，你可以根据自己的实际需求来调整这些原则。</p><p>接下来我们再来看看这个模版右侧的“会议执行步骤”，也就是会议该如何进行？</p><p>首先是准时开始，然后，会议负责人欢迎大家，此时负责人应该帮助与会者感到宾至如归。第三步，会议负责人向与会者简短的演示或培训有关会议内容、工具资源等相关内容，这个过程应该控制在大约三到五分钟内。</p><p>小组会议议程的第四步是让每个人快速报告他们在上次会议上所做的承诺，逐个询问每个人是否做到了，与会者回答是或否。接下来，将会议剩余时间减去五分钟留作总结时间，其余时间在成员之间平均分配，确保每个与会者都有发言权。举个例子，如果剩下30分钟并且有五个参与者，那么每个人将有五分钟的发言时间。</p><p>在最后五分钟内，会议负责人或会议记录员需要回顾并总结每个人在会议期间所做的承诺，然后再次确认下次会议的日期和时间。如果是轮换会议负责人的方式，还要确认下次会议的会议负责人。最后，尽量尽早结束会议，最好不要超时，通常会议时间越短效果越好。</p><h2 id="跟进承诺任务" tabindex="-1">跟进承诺任务 <a class="header-anchor" href="#跟进承诺任务" aria-label="Permalink to &quot;跟进承诺任务&quot;">​</a></h2><p>与会者在上次会议中确定的工作任务或承诺，需要在本次会议时进行汇报。这个过程实际上非常简单，会议负责人利用上一次会议的会议记录，朗读每个人的承诺，并简单地问道：“你这样做了吗？”，如果答案是肯定的，那么会议负责人可以提供简短的回答，如 “干得好” 或 “谢谢”。</p><p>但如果答案是否定的，会议负责人需要问对方“是什么妨碍你完成？” 或者 “遇到了什么障碍？”等类似的问题， 这比询问诸如 “你为什么不这样做？” 之类的问题要有效得多，因为后者非常强硬，并且经常会让人感觉是责备。这里我们不想责备或羞辱他人，相反，我们是要试图找到帮助他们完成工作的解决方案。</p><p>会议负责人应避免参与有关此人未完成承诺工作的延伸讨论，我们需要的只是简要解释发生的事情。如果此说明生成了一个主题，小组或会议负责人希望与所有与会者进一步讨论，那么可以将其添加到任务列表中，以便稍后讨论。</p><p>如果他们未能完成任务，则需要让他们对完成任务的日期和时间作出新的承诺，并在新的期限之前完成它。</p><p>在收到关于上次会议的待办事项或任务列表完成情况的简要报告后，你需要在其之上记录任何新的承诺，然后保持会议继续进行。通过采用这种方法，你可以提高承诺的完成率，并使会议更有意义。</p><p>如果你发现某人一直未能完成承诺的工作，那就需要进行一对一会议沟通了，而不要在小组会议中直接进行批评或指责。一对一会议是管理者协助员工履行承诺，以及探索导致员工缺乏后续行动力的深层原因的好方法。</p><p>另外，在会议上，你可以寻找每个参与者都做得好的事情并对其进行评论，给予对方简短、真诚的赞美，表明你已经看到他们的努力和付出。</p><h2 id="结束会议" tabindex="-1">结束会议 <a class="header-anchor" href="#结束会议" aria-label="Permalink to &quot;结束会议&quot;">​</a></h2><p>会议议程的最后一步是审查每个人的待办事项或工作任务，在整个会议期间，与会者可能都已经承诺将在某个时间内完成某些事情，通常在这一点上，会议负责人会将其转交给记录员，并要求他们总结承诺。</p><p>会议记录员会使用“谁、什么和何时”这三个要素总结每个人的承诺。换句话说，谁做出了承诺，他们要做什么，他们将在何时实现它，就这么简单。</p><p>在会议记录员通读列表时，每个与会者都应该密切关注并确保他们同意正在审核的承诺。</p><p>在审核了每个人的待办事项后，会议负责人就可以结束会议了，可以通过简单地确认下次会议的时间、会议地点以及确认任何其他会议来做到这一点。</p><p>如果需要在常规会议日程之外更详细地讨论有争议的话题，会议负责人将提醒每个人特别会议，并确保会议排上了他们的日程。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本文中，我们已经探讨了一个可以在任何公司使用的高效会议框架，以提高会议效率并专注于结果为目的。如果你遵循本指南的建议，会议的有效性及效率应该得到改善，我希望确保你的会议每次都变得更好，最好的方法是制定一个计划，不断重新评估会议的有效性，也许可以每季度一次，使用会议的一部分时间向每位与会者询问 “这些会议是否有效？”，并根据反馈不断改进。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在介绍完高效会议指南后，咱们不妨在此思考下，接下来你要进行每周工作回顾会议，使用本文的操作方法或技巧，该怎么来准备、执行会议并保证会议执行的有效且高效呢？</p><p>感谢你的收听，我们下期再见！</p><h2 id="作者介绍" tabindex="-1">作者介绍 <a class="header-anchor" href="#作者介绍" aria-label="Permalink to &quot;作者介绍&quot;">​</a></h2><p>刘俊强（微信公众号：程序员精进）现任腾讯云资深架构师，曾任迅雷技术总监、某互联网公司技术副总裁，10+年以上互联网开发经验，8年以上技术管理经验。</p>',35)])])}const u=a(p,[["render",r]]);export{c as __pageData,u as default};
